function usable = rowsUsableForDiffusion(tableData, opts)
    import membrane_tracking.focused_ism.*

    usable = tableData.associationProbability >= ...
            opts.minAssociationProbabilityForDiffusion & ...
        tableData.emitterCountPosteriorProbability >= ...
            opts.minEmitterCountPosteriorProbabilityForDiffusion;
    if ismember('positionIdentifiable', ...
            tableData.Properties.VariableNames)
        usable = usable & logical(tableData.positionIdentifiable);
    end
end
